CALL bank_lab.sp_expect_error(DATABASE(),'register NULL phone','CALL {db}.sp_register_customer(''Synthetic'',''1990-01-01'',NULL,CONCAT(''null.'',@p3_tag,''@example.invalid''),NULL,''Synthetic'',CONCAT(''SYN6-'',LEFT(@p3_tag,24)),''PAN'',@p3_new)',5018);
CALL bank_lab.sp_expect_error(DATABASE(),'register NULL address','CALL {db}.sp_register_customer(''Synthetic'',''1990-01-01'',NULL,CONCAT(''null.'',@p3_tag,''@example.invalid''),@p3_phone,NULL,CONCAT(''SYN6-'',LEFT(@p3_tag,24)),''PAN'',@p3_new)',5018);
CALL bank_lab.sp_expect_error(DATABASE(),'register NULL proof','CALL {db}.sp_register_customer(''Synthetic'',''1990-01-01'',NULL,CONCAT(''null.'',@p3_tag,''@example.invalid''),@p3_phone,''Synthetic'',NULL,''PAN'',@p3_new)',5018);
CALL bank_lab.sp_expect_ok(DATABASE(),'register plus phone accepted','CALL {db}.sp_register_customer(''Synthetic plus phone'',''1990-01-01'',NULL,CONCAT(''plus.'',@p3_tag,''@example.invalid''),CONCAT(''+6'',LPAD(MOD(UUID_SHORT(),1000000000),9,''0'')),''Synthetic'',CONCAT(''SYN6-'',LEFT(@p3_tag,24)),''PAN'',@p3_new)');
